// Concatenated query on a 'search' endpoint
String term = request.getParameter("q");
String sql = "SELECT * FROM products WHERE name LIKE '%" + term + "%'";
statement.execute(sql);

// Attacker supplies q =  %'; UPDATE users SET role='ADMIN' WHERE id=42; --
// If the driver allows batched statements, they just promoted themselves.
// q =  %'; DROP TABLE audit_log; --   destroys data outright.
```

```java
// 1) Parameterize so injection is impossible in the first place
String sql = "SELECT * FROM products WHERE name LIKE ?";
try (PreparedStatement ps = connection.prepareStatement(sql)) {
    ps.setString(1, "%" + term + "%");
    ps.executeQuery();
}
```
