-- 2) Defense in depth: the app's DB user can only read products
CREATE USER app_ro WITH PASSWORD '...';
GRANT SELECT ON products TO app_ro;   -- no UPDATE/DELETE/DROP
-- Even a missed injection can't modify or destroy data.
```
*Parameterization prevents the attack; least privilege caps the blast radius if anything slips through.*

```java
// You CANNOT bind a column name with ?. Validate it against an allowlist.
private static final Set<String> SORTABLE =
    Set.of("name", "price", "created_at"); // known-good columns only

public List<Product> search(String term, String sortColumn) {
    if (!SORTABLE.contains(sortColumn)) {
        throw new IllegalArgumentException("Invalid sort column"); // reject
    }
    // term is bound; sortColumn is from a trusted allowlist, not raw input
    String sql = "SELECT * FROM products WHERE name LIKE ? ORDER BY " + sortColumn;
    try (PreparedStatement ps = connection.prepareStatement(sql)) {
        ps.setString(1, "%" + term + "%");
        // ... map ResultSet to Product ...
    }
    return List.of();
}
```
*Values use `?`; the one thing that can't be a parameter (the column name) is constrained to a fixed allowlist.*
